"""Per-key token bucket replayed over a timeline of events. See task.md."""

from __future__ import annotations

import math
from fractions import Fraction
from typing import NamedTuple


class ConfigError(ValueError):
    """Raised for an unusable config and for an unusable event stream."""


class Event(NamedTuple):
    timestamp_ms: int
    key: str
    cost: int


class Decision(NamedTuple):
    allowed: bool
    remaining: int
    retry_after_ms: int


def decide(config: dict, events: list[Event]) -> list[Decision]:
    """Replay `events` through a per-key token bucket, one Decision each."""
    capacity = config.get("capacity")
    refill_tokens = config.get("refill_tokens")
    refill_interval_ms = config.get("refill_interval_ms")

    if capacity is None or refill_tokens is None or refill_interval_ms is None:
        raise ConfigError("capacity, refill_tokens and refill_interval_ms are required")
    if capacity < 1:
        raise ConfigError("capacity must be at least 1")
    if refill_tokens < 1:
        raise ConfigError("refill_tokens must be at least 1")
    if refill_interval_ms < 1:
        raise ConfigError("refill_interval_ms must be at least 1")

    initial_tokens = config.get("initial_tokens", capacity)
    if initial_tokens < 0 or initial_tokens > capacity:
        raise ConfigError("initial_tokens must be between 0 and capacity")

    prev_t = None
    for event in events:
        if event.cost < 0:
            raise ConfigError("event cost must not be negative")
        if prev_t is not None and event.timestamp_ms < prev_t:
            raise ConfigError("events must be sorted by timestamp_ms")
        prev_t = event.timestamp_ms

    rate = Fraction(refill_tokens, refill_interval_ms)
    buckets: dict[str, tuple[Fraction, int]] = {}
    decisions: list[Decision] = []

    for t, key, cost in events:
        if key in buckets:
            tokens, last_t = buckets[key]
            tokens = tokens + (t - last_t) * rate
            if tokens > capacity:
                tokens = Fraction(capacity)
        else:
            tokens = Fraction(initial_tokens)

        if cost > capacity:
            decisions.append(Decision(False, math.floor(tokens), -1))
        elif tokens >= cost:
            tokens -= cost
            decisions.append(Decision(True, math.floor(tokens), 0))
        else:
            needed = cost - tokens
            wait = math.ceil(needed / rate)
            decisions.append(Decision(False, math.floor(tokens), wait))

        buckets[key] = (tokens, t)

    return decisions
